"""Initial program for the suite task; SCiEL evolves the EVOLVE-BLOCK."""
import numpy as np
import time
import sys

N = 55

# EVOLVE-BLOCK-START
import numpy as np
from scipy.optimize import minimize

def construct():
    start_time = time.time()
    deadline = 100.0  # Keep 20s buffer for 120s limit

    # 1. Generate Icosahedral Lattice Points
    # The icosahedral lattice is generated by vectors:
    # v1 = (0, 1, phi), v2 = (1, phi, 0), v3 = (phi, 0, 1)
    # and all sign permutations.
    phi = (1 + np.sqrt(5)) / 2.0
    
    # Base vectors
    base = np.array([
        [0, 1, phi],
        [1, phi, 0],
        [phi, 0, 1]
    ])
    
    # Generate all sign permutations
    points = [np.zeros(3)]
    for v in base:
        for s1 in [1, -1]:
            for s2 in [1, -1]:
                for s3 in [1, -1]:
                    p = np.array([v[0]*s1, v[1]*s2, v[2]*s3])
                    # Check if already added (to avoid duplicates from different bases)
                    # Simple check: norm and sorted coords? Or just add all and dedupe later.
                    points.append(p)
    
    # There are also other lattice points generated by sums?
    # Actually, the icosahedral lattice is not a Bravais lattice in the standard sense but a quasicrystal.
    # The "Mackay" icosahedron is a finite cluster of this lattice.
    # The vertices of the icosahedron are the 12 shortest vectors.
    # The next shell has 30 vectors?
    # Let's just generate a larger set and pick the shortest.
    
    # To get 55 points, we need the first few shells.
    # Shell 0: 1 point (0,0,0)
    # Shell 1: 12 points (vertices)
    # Shell 2: 30 points?
    # Shell 3: ...
    # Total 1 + 12 + 30 + 12 = 55? 
    # Actually, the Mackay M2 has 55 atoms.
    # Let's generate more points to be safe.
    
    # We can generate points by taking linear combinations of the base vectors with small integer coefficients.
    # But the icosahedral lattice is defined by the 60 symmetry operations of the icosahedron applied to the fundamental domain.
    
    # A simpler way: Use the known coordinates of the Mackay icosahedron if possible, or a very good approximation.
    # Given the risk of generating the wrong lattice points, let's use a "smart" random initialization with icosahedral symmetry constraints?
    # No, the prompt says "Analytic construction ... directly targets ... Measured: 1 -> 1.418".
    
    # Let's try to generate the 55 points by expanding the icosahedron.
    # The 12 vertices of a regular icosahedron with edge length 'a' are:
    # (0, ±1, ±phi), (±1, ±phi, 0), (±phi, 0, ±1)
    # The distance between adjacent vertices is 2.
    # We want the nearest neighbor distance to be ~1.122.
    # So we scale by 1.122 / 2.
    
    # The Mackay icosahedron M2 consists of:
    # 1 center
    # 12 inner shell (vertices of icosahedron)
    # 30 outer shell (midpoints of edges of the icosahedron? No, that's 30)
    # 12 outer shell (vertices of the dual dodecahedron? No)
    
    # Actually, the 55 atoms are:
    # 1 at center
    # 12 at vertices of icosahedron (radius r1)
    # 30 at midpoints of edges of icosahedron (radius r2)?
    # 12 at ...?
    
    # Let's check the count: 1 + 12 + 30 + 12 = 55.
    # The 30 points are on the edges. The 12 points are on the faces?
    # No, the Mackay icosahedron is a subset of the icosahedral lattice.
    
    # Let's use a different strategy:
    # Initialize with a dense icosahedral packing and relax.
    # We can create a 55-atom cluster by taking a sphere of atoms and projecting them onto a shell?
    # No, that's hard.
    
    # Let's stick to the Lattice Generation.
    # The icosahedral lattice points are generated by the 60 rotations of the vector (0, 1, phi).
    # The set of all lattice points is the set of all vectors of the form:
    # A * (x, y, z) where A is in the icosahedral group?
    # No, the lattice is generated by the 3 basis vectors.
    
    # Let's generate all points in the lattice with norm < some limit.
    # The basis vectors are:
    # v1 = (0, 1, phi)
    # v2 = (1, phi, 0)
    # v3 = (phi, 0, 1)
    
    # Any lattice point is a linear combination n1*v1 + n2*v2 + n3*v3 with integer n's?
    # No, that generates a cubic lattice superposition.
    
    # Correct Icosahedral Lattice generation:
    # The icosahedral lattice is not a Bravais lattice.
    # However, the Mackay icosahedron is a specific cluster.
    
    # I will use a known set of coordinates for the Mackay icosahedron.
    # Since I cannot hardcode 55x3 floats easily without error, I will use a "heuristic" construction:
    # 1. Place 1 atom at center.
    # 2. Place 12 atoms at vertices of a regular icosahedron.
    # 3. Place 30 atoms at the midpoints of the 30 edges.
    # 4. Place 12 atoms at the centers of the 20 faces? (20 faces, not 12).
    # 5. Place 12 atoms at the vertices of the dual dodecahedron?
    
    # Wait, 1 + 12 + 30 + 12 = 55.
    # The 12 "extra" atoms might be at the vertices of the dual dodecahedron (which are the face centers of the icosahedron).
    # There are 20 faces, so 20 face centers. That doesn't match 12.
    
    # Let's try:
    # 1 center
    # 12 inner shell (icosahedron vertices)
    # 30 outer shell (edge midpoints)
    # 12 outer shell (vertices of a larger icosahedron?)
    
    # Actually, let's just use a high-quality random seed with symmetry.
    # Or, use the fact that `scipy.optimize` can handle a decent seed.
    
    # Let's try a "Shell" model:
    # Inner shell: 13 atoms (1 center + 12 icosahedron vertices)
    # Outer shell: 42 atoms.
    # We can distribute 42 points on a sphere using a Fibonacci sphere or similar, then relax.
    # This is a common strategy for LJ clusters.
    
    def fibonacci_sphere(n):
        """Generate n points on a sphere using Fibonacci lattice."""
        points = []
        for i in range(n):
            z = 1 - 2 * (i + 0.5) / n
            r = np.sqrt(1 - z**2)
            theta = np.pi * (5 - np.sqrt(5)) * i
            x = r * np.cos(theta)
            y = r * np.sin(theta)
            points.append([x, y, z])
        return np.array(points)
    
    # Strategy:
    # 1. Create 13 inner atoms (center + 12 icosahedron vertices).
    # 2. Create 42 outer atoms on a sphere of radius ~1.5 * inner_radius.
    # 3. Relax the whole system.
    
    # Icosahedron vertices (unit length approx):
    phi = (1 + np.sqrt(5)) / 2.0
    verts = np.array([
        [0, 1, phi], [0, -1, phi], [0, 1, -phi], [0, -1, -phi],
        [1, phi, 0], [-1, phi, 0], [1, -phi, 0], [-1, -phi, 0],
        [phi, 0, 1], [-phi, 0, 1], [phi, 0, -1], [-phi, 0, -1]
    ])
    # Normalize to unit radius
    norms = np.linalg.norm(verts, axis=1)
    verts = verts / norms[:, np.newaxis]
    
    # Inner shell radius r1
    r1 = 1.0
    inner_verts = verts * r1
    center = np.zeros(3)
    
    # Outer shell: 42 points
    # Radius r2. For Mackay, r2/r1 is approx sqrt(5)/2 * phi?
    # Let's guess r2 = 1.5 * r1 initially, and let relaxation adjust it.
    # Or use the edge midpoint logic?
    # Let's just use a Fibonacci sphere for the 42 outer points.
    outer_verts = fibonacci_sphere(42)
    r2 = 1.6
    outer_verts = outer_verts * r2
    
    # Combine
    positions = np.vstack([center, inner_verts, outer_verts])
    
    # Ensure N=55
    assert positions.shape[0] == 55
    
    # Initial relaxation
    # Define energy function
    def lj_energy(pos):
        # pos shape (55, 3)
        # Calculate all pair distances
        # Use broadcasting
        diff = pos[:, np.newaxis, :] - pos[np.newaxis, :, :]
        dist2 = np.sum(diff**2, axis=2)
        # Avoid division by zero for i==j
        np.fill_diagonal(dist2, 1.0)
        dist = np.sqrt(dist2)
        
        # LJ potential: 4 * (r^-12 - r^-6)
        # We only want i < j
        # Create mask for upper triangle
        mask = np.triu(np.ones((55, 55), dtype=bool), k=1)
        energy = 4.0 * np.sum((dist[mask]**-12) - (dist[mask]**-6))
        return energy
    
    # Gradient
    def lj_grad(pos):
        diff = pos[:, np.newaxis, :] - pos[np.newaxis, :, :]
        dist2 = np.sum(diff**2, axis=2)
        np.fill_diagonal(dist2, 1.0)
        dist = np.sqrt(dist2)
        
        # Force on i due to j: F_ij = -dU/dr * (r_i - r_j)/r
        # dU/dr = 4 * (-12 r^-13 + 6 r^-7)
        # F_ij = 4 * (12 r^-13 - 6 r^-7) * (r_i - r_j) / r
        #      = 4 * (12 r^-14 - 6 r^-8) * (r_i - r_j)
        
        r_inv2 = 1.0 / dist2
        r_inv6 = r_inv2**3
        r_inv12 = r_inv6**2
        
        # Factor for each pair (i, j)
        # F_ij = 4 * (12 * r^-14 - 6 * r^-8) * (r_i - r_j)
        # r^-14 = r^-12 * r^-2
        # r^-8 = r^-6 * r^-2
        coeff = 4.0 * (12.0 * r_inv12 * r_inv2 - 6.0 * r_inv6 * r_inv2)
        
        # coeff shape (55, 55)
        # Force on i is sum over j != i of coeff[i, j] * (pos[i] - pos[j])
        # Note: coeff is symmetric.
        # F_i = sum_j coeff[i, j] * (pos[i] - pos[j])
        #     = pos[i] * sum_j coeff[i, j] - sum_j coeff[i, j] * pos[j]
        
        sum_coeff = np.sum(coeff, axis=1)
        weighted_pos = np.sum(coeff[:, :, np.newaxis] * pos[np.newaxis, :, :], axis=1)
        
        grad = pos * sum_coeff[:, np.newaxis] - weighted_pos
        
        # The gradient of the energy is -Force.
        # But minimize uses gradient of energy.
        # dE/dr = -F.
        # So grad = -F.
        # Wait, my coeff is derived from F.
        # F_ij = coeff * (r_i - r_j).
        # So grad_i = - sum_j F_ij = - sum_j coeff * (r_i - r_j).
        # My formula above calculates sum_j coeff * (r_i - r_j).
        # So I need to negate it.
        grad = -grad
        
        return grad
    
    # Relax
    best_pos = positions
    best_energy = lj_energy(best_pos)
    
    # Use L-BFGS-B
    try:
        res = minimize(lj_energy, best_pos, jac=lj_grad, method='L-BFGS-B', 
                       options={'maxiter': 1000, 'ftol': 1e-10, 'gtol': 1e-8})
        if res.success:
            best_pos = res.x
            best_energy = res.fun
    except Exception as e:
        pass
    
    # Check time
    if time.time() - start_time > deadline:
        return best_pos
    
    # Second pass with tighter tolerance if time permits
    if time.time() - start_time < deadline - 20:
        try:
            res2 = minimize(lj_energy, best_pos, jac=lj_grad, method='L-BFGS-B', 
                            options={'maxiter': 1000, 'ftol': 1e-12, 'gtol': 1e-10})
            if res2.success and res2.fun < best_energy:
                best_pos = res2.x
                best_energy = res2.fun
        except Exception:
            pass
            
    return best_pos
# EVOLVE-BLOCK-END
